// One row per target, so a failure is visible in the execution list
// rather than buried in a response body.
const checks = [
  { target: 'api', node: 'Wake API' },
  { target: 'ui',  node: 'Check UI' },
];

const results = checks.map(({ target, node }) => {
  let status = 0;
  try {
    status = $(node).first().json.statusCode ?? 0;
  } catch (e) {
    status = 0;
  }
  return {
    json: {
      target,
      status,
      ok: status >= 200 && status < 400,
      checkedAt: new Date().toISOString(),
    },
  };
});

const failed = results.filter((r) => !r.json.ok).map((r) => r.json.target);
if (failed.length) {
  // Surfaces as a failed execution so n8n's own alerting can catch it.
  throw new Error(`Unreachable: ${failed.join(', ')}`);
}

return results;
